<script setup>
import { workflowNodeSkipped } from '../../../../src/shared/workflow-conditions.js';
import { computed, ref, watch } from 'vue';
import { withImageToken } from '../../api/tools/imageCropper.js';
import { applyWorkflowBindings } from '../../../../src/shared/product-workflow-bindings.js';
import { readableWorkflowValue } from '../../../../src/shared/product-workflow-inputs.js';
const props=defineProps({record:{type:Object,required:true},job:{type:Object,default:()=>({})},busy:Boolean});
const emit=defineEmits(['action','finish','open-draft','editing']);
const active=ref(0);
watch(()=>props.record.id,()=>{active.value=0;});
const payload=computed(()=>props.record.payload);
const variant=computed(()=>payload.value.variants[active.value]||payload.value.variants[0]);
const nodes=computed(()=>payload.value.definition.nodes.filter(n=>['image','copy','video','approval'].includes(n.type)&&!workflowNodeSkipped(n,variant.value)));
const results=computed(()=>payload.value.outputs[variant.value.id]||{});
const facts=computed(()=>payload.value.definition.nodes.filter(n=>['field','attribute'].includes(n.type)));
const assembly=computed(()=>{
  if(!payload.value.definition.bindings)return null;
  try{return {value:applyWorkflowBindings(payload.value.definition,variant.value,Object.fromEntries(Object.entries(results.value).map(([id,state])=>[id,{...state,approved:true}])))};}
  catch(error){return {error:error.message};}
});
const allGenerated=computed(()=>payload.value.variants.every(v=>payload.value.definition.nodes.filter(n=>['image','copy','video'].includes(n.type)&&!workflowNodeSkipped(n,v)).every(n=>payload.value.outputs[v.id]?.[n.id]?.url||payload.value.outputs[v.id]?.[n.id]?.text)));
const act=(action,node,extra={})=>emit('action',{id:props.record.id,action,nodeId:node.id,variantId:variant.value.id,...extra});
const blockedNodes=computed(()=>payload.value.variants.flatMap(v=>payload.value.definition.nodes.filter(n=>['image','copy','video'].includes(n.type)).filter(n=>['failed','unknown'].includes(payload.value.outputs[v.id]?.[n.id]?.status)).map(node=>({node,variant:v,state:payload.value.outputs[v.id][node.id]}))));
function readableError(error){const text=String(error||'');if(/Duplicate entry.*ai_generation_task_no/i.test(text))return '原图片任务已存在，点击“继续执行”恢复原任务，不会重复生图。';if(/fetch failed|ECONNRESET|ETIMEDOUT/i.test(text))return '模型服务连接中断，请重试失败节点；已生成的内容会保留。';return text;}
const needsRecovery=state=>state?.status==='unknown'||state?.taskId&&!state.url&&state.failureKind!=='provider_confirmed';
const copyChanged=node=>{emit('editing',false);act('save-copy',node,{text:JSON.parse(JSON.stringify(results.value[node.id].text))});};
</script>
<template>
  <div class="review-head"><div><h3>{{ payload.definition.name }}</h3><p>{{ payload.variants.length }} 个变体 · {{ payload.definition.category?.categoryName }} · 任务 {{ record.id.slice(0,8) }}</p></div><el-button v-if="payload.draftId" type="primary" @click="emit('open-draft',payload.draftId)">预览商品并选择店铺上架</el-button><el-button v-else-if="allGenerated&&['awaiting_review','ready'].includes(job.status)" type="primary" :disabled="busy" @click="emit('finish')">整套检查通过，完成生产</el-button></div>
  <section v-if="!payload.draftId&&(['failed','awaiting_review','ready'].includes(job.status)||!job.status)" class="task-recovery">
    <div class="review-head"><h4>{{ job.status==='failed'?'任务需要处理':'下一步操作' }}</h4><el-button v-if="!blockedNodes.length&&job.status!=='ready'" type="primary" :loading="busy" @click="emit('action',{id:record.id,action:'start'})">{{ job.status?'继续执行':'提交后台执行' }}</el-button></div>
    <p>{{ blockedNodes.length?'已生成的内容会保留，请处理以下节点后继续。':job.status==='failed'?'请先核对下方失败原因。权限或通道问题解决后，可点击继续执行；模板和材料需调整时，请返回流程重新生产。':'请检查下面已生成的图片和文案；确认主图后，后台继续生成后续内容。' }}</p>
    <div v-for="item in blockedNodes" :key="`${item.variant.id}:${item.node.id}`" class="blocked-node"><div><strong>{{ item.variant.label }} · {{ item.node.label }}</strong><p>{{ readableError(item.state.error||job.error_message)||'生成未完成，请重试' }}</p></div><el-button type="primary" :disabled="busy" @click="emit('action',{id:record.id,action:'retry',nodeId:item.node.id,variantId:item.variant.id})">{{ item.node.type==='image'&&needsRecovery(item.state)?'核对并恢复原任务':'重试此节点' }}</el-button></div>
  </section>
  <el-alert v-if="job.error_message" :title="readableError(job.error_message)" :type="job.status==='failed'?'error':'warning'" :closable="false"/>
  <el-alert v-else type="info" :closable="false" title="后台自动推进生产。确认主图后自动继续；检查完整套图与文案后完成生产，再预览编辑并选择店铺上架。"/>
  <el-radio-group v-model="active" class="variant-tabs"><el-radio-button v-for="(v,i) in payload.variants" :key="v.id" :value="i">{{ v.label }}</el-radio-button></el-radio-group>
  <el-collapse><el-collapse-item title="预览本变体的产品资料与上架属性" name="facts"><el-descriptions :column="2" border><el-descriptions-item v-for="node in facts" :key="node.id" :label="node.label">{{ readableWorkflowValue(node,variant.values[node.id])||'未填写' }}</el-descriptions-item></el-descriptions></el-collapse-item></el-collapse>
  <el-collapse v-if="assembly"><el-collapse-item title="预览模板字段装配结果（按当前绑定）" name="assembly"><p v-if="assembly.error">{{ assembly.error }}</p><template v-else><el-descriptions :column="1" border><el-descriptions-item label="标题">{{ assembly.value.title||'上架前补齐' }}</el-descriptions-item><el-descriptions-item label="标签">{{ assembly.value.tags.join(' ')||'未配置' }}</el-descriptions-item><el-descriptions-item label="简介">{{ assembly.value.description||'未配置' }}</el-descriptions-item><el-descriptions-item label="富文本">{{ assembly.value.rich_content_json?'已按绑定图片和文本组合':'未配置' }}</el-descriptions-item></el-descriptions><div class="assembled-images"><el-image v-for="(image,index) in assembly.value.images" :key="index" :src="withImageToken(image.url)" :preview-src-list="assembly.value.images.map(i=>withImageToken(i.url))" :initial-index="index" preview-teleported fit="contain"/></div></template></el-collapse-item></el-collapse>
  <div class="review-grid"><article v-for="node in nodes" :key="node.id"><div class="review-head"><h4>{{ node.label }}</h4><el-tag :type="results[node.id]?.approved?'success':'info'">{{ results[node.id]?.approved?'已确认':results[node.id]?.url||results[node.id]?.text?'待检查':results[node.id]?.status==='failed'?'失败':results[node.id]?.status==='unknown'?'待核对':results[node.id]?.phase==='queued'?'排队中':results[node.id]?.phase==='provider_pending'?'原任务恢复中':results[node.id]?.taskId?'生成中':'等待前序' }}</el-tag></div>
    <template v-if="node.type==='image'"><el-image v-if="results[node.id]?.url" :src="withImageToken(results[node.id].url)" :preview-src-list="[withImageToken(results[node.id].url)]" preview-teleported fit="contain"/><div v-else class="placeholder">{{ node.role==='main'?'变体主图':'详情图' }} · {{ node.ratio }}</div></template>
    <template v-if="node.type==='video'"><video v-if="results[node.id]?.url" :src="withImageToken(results[node.id].url)" controls preload="metadata" style="width:100%;max-height:280px"/><p v-else>使用生成的主图制作上架视频</p></template><template v-if="node.type==='approval'"><p>检查 {{ node.inputs.map(id=>payload.definition.nodes.find(n=>n.id===id)?.label).join('、') }}</p><el-button v-if="!results[node.id]?.approved&&!payload.draftId" type="success" :disabled="busy||!node.inputs.every(id=>results[id]?.url||results[id]?.approved)" @click="act('approve',node)">主图确认，后台继续生成</el-button></template>
    <template v-if="node.type==='copy'&&results[node.id]?.text"><label v-if="'text'in results[node.id].text">{{ node.label }}<el-input v-model="results[node.id].text.text" type="textarea" :rows="4" :disabled="Boolean(payload.draftId)" @focus="emit('editing',true)" @blur="emit('editing',false)" @change="copyChanged(node)"/></label><label v-if="'title'in results[node.id].text">标题<el-input v-model="results[node.id].text.title" :disabled="Boolean(payload.draftId)" @focus="emit('editing',true)" @blur="emit('editing',false)" @change="copyChanged(node)"/></label><label v-if="'tags'in results[node.id].text">标签<el-select v-model="results[node.id].text.tags" multiple filterable allow-create :disabled="Boolean(payload.draftId)" @visible-change="emit('editing',$event)" @change="copyChanged(node)"><el-option v-for="tag in results[node.id].text.tags" :key="tag" :label="tag" :value="tag"/></el-select></label><label v-if="'description'in results[node.id].text">描述<el-input v-model="results[node.id].text.description" type="textarea" :rows="4" :disabled="Boolean(payload.draftId)" @focus="emit('editing',true)" @blur="emit('editing',false)" @change="copyChanged(node)"/></label></template>
    <p v-if="results[node.id]?.progressMessage" class="progress-message">{{ results[node.id].progressMessage }}</p><p v-if="results[node.id]?.error" class="error">{{ readableError(results[node.id].error) }}</p>
    <div v-if="!payload.draftId&&node.type!=='approval'" class="review-actions"><el-button v-if="(results[node.id]?.url||results[node.id]?.text)&&!results[node.id]?.approved" :disabled="busy" @click="act('approve',node)">检查通过</el-button><el-button v-if="results[node.id]&&!['running','submitting'].includes(results[node.id].status)" :disabled="busy" text @click="act('retry',node)">{{ (results[node.id]?.status==='unknown'||node.type==='image'&&results[node.id]?.taskId&&!results[node.id]?.url&&results[node.id]?.failureKind!=='provider_confirmed')?'核对并恢复原任务':'重生成本节点' }}</el-button></div>
  </article></div>
</template>
<style scoped>
.task-recovery{padding:16px;border:1px solid var(--el-border-color);border-radius:8px;margin-bottom:16px;background:var(--el-fill-color-light)}.blocked-node{display:flex;justify-content:space-between;align-items:center;gap:16px;padding-top:12px;border-top:1px solid var(--el-border-color-lighter)}.blocked-node p{overflow-wrap:anywhere}.assembled-images{display:flex;gap:12px;flex-wrap:wrap;margin:12px 0}.assembled-images .el-image{width:100px;height:134px}.review-head{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:12px}.review-head h3,.review-head h4{margin:0}.review-head p{color:var(--el-text-color-secondary)}.variant-tabs{margin:18px 0}.review-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:16px}.review-grid article{padding:16px;border:1px solid var(--el-border-color-lighter);border-radius:8px;min-width:0;background:var(--el-bg-color)}.review-grid .el-image{width:100%;height:280px;background:var(--el-fill-color-lighter)}.placeholder{height:180px;display:grid;place-items:center;background:var(--el-fill-color-light);color:var(--el-text-color-secondary)}label{display:block;margin:12px 0}label .el-input,label .el-select{margin-top:6px;width:100%}.review-actions{display:flex;flex-wrap:wrap;margin-top:12px;gap:8px}.error{color:var(--el-color-danger)}
</style>
